import sys

def is_correct_parenthesis_sequence(s):
    balance = 0
    for c in s:
        if c == '(':
            balance += 1
        elif c == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def solve(s):
    n = len(s)
    result = list(s)
    open_count = 0
    close_needed = 0

    for i in range(n):
        if result[i] == '(':
            open_count += 1
        elif result[i] == ')':
            close_needed += 1
        else:
            if open_count < close_needed + 1:
                result[i] = '('
                open_count += 1
            else:
                result[i] = ')'
                close_needed += 1

        if open_count < close_needed:
            return ':('

    if open_count != close_needed:
        return ':('

    for i in range(1, n):
        if is_correct_parenthesis_sequence(''.join(result[:i])):
            return ':('

    return ''.join(result)

input = sys.stdin.read().split()
n = int(input[0])
s = input[1]
print(solve(s))
